def solve(grid):
    rows = len(grid)
    cols = len(grid[0])

    # For each column, find where the 5s start (from bottom going up)
    # and compute the length of the contiguous 5s from the bottom
    columns_with_5s = []
    for c in range(cols):
        # Find the topmost row where 5 appears in a contiguous block from the bottom
        length = 0
        for r in range(rows - 1, -1, -1):
            if grid[r][c] == 5:
                length += 1
            else:
                break
        if length > 0:
            columns_with_5s.append((c, length))

    # Sort by length descending (longest gets label 1, next gets 2, etc.)
    columns_with_5s.sort(key=lambda x: -x[1])

    # Assign labels
    result = [row[:] for row in grid]
    for idx, (c, length) in enumerate(columns_with_5s):
        label = idx + 1
        start_row = rows - length
        for r in range(start_row, rows):
            result[r][c] = label

    return result

